import { compare } from '@sveltia/utils/string';

import { allAssetFolders, selectedAssetFolder } from '$lib/services/assets/folders';
import { isCmsFolderName, isCmsFolderPath } from '$lib/services/assets/reserved';
import { allAssets } from '$lib/services/assets/state';
import { gitConfigFiles } from '$lib/services/backends/git/shared/config';
import { slugify, validateNewFolderName } from '$lib/services/common/slug';
import { allEntries } from '$lib/services/contents';
import { getDefaultMediaLibraryOptions } from '$lib/services/integrations/media-libraries/default';
import { getOrCreate, memoizeOnSource, memoizeOnSources } from '$lib/services/utils/cache';
import {
  createPath,
  getBaseName,
  getDirName,
  renameReservedFileName,
  sanitizeFileName,
} from '$lib/services/utils/file';
import { createDerivedState, createRawState } from '$lib/services/utils/state.svelte';

/**
 * @import {
 * Asset,
 * AssetFolderInfo,
 * AssetSubfolder,
 * BreadcrumbItem,
 * UploadingAssets,
 * } from '$lib/types/private';
 */

/**
 * Path of the subfolder being browsed below the selected asset folder’s `internalPath`, relative to
 * it. Empty at the folder root, and always empty for a folder that can’t be browsed by subfolder.
 * @type {{ current: string }}
 */
export const selectedSubfolderPath = createRawState('');

/**
 * Subfolder currently focused in the Asset Library, whose info is shown in the sidebar, if any.
 * @type {{ current: AssetSubfolder | undefined }}
 */
export const focusedSubfolder = createRawState();

/**
 * Subfolder being renamed with the Rename Folder dialog, if any.
 * @type {{ current: AssetSubfolder | undefined }}
 */
export const renamingSubfolder = createRawState();

/**
 * Subfolder being deleted with the Delete Folder dialog, if any.
 * @type {{ current: AssetSubfolder | undefined }}
 */
export const deletingSubfolder = createRawState();

/**
 * Check if the given asset folder can be browsed by subfolder, which takes a folder whose files all
 * sit below one fixed path: an entry-relative folder is scattered across the entry folders, and a
 * folder with template tags is only resolved per entry, so neither has a single tree to walk. The
 * All Assets folder has no path at all. The assets of such a folder are all listed at once.
 * @param {AssetFolderInfo | undefined} folder Asset folder.
 * @returns {folder is AssetFolderInfo} Result.
 */
export const canBrowseSubfolders = (folder) =>
  !!folder && folder.internalPath !== undefined && !folder.entryRelative && !folder.hasTemplateTags;

/**
 * Get the path of a file or directory relative to a base directory.
 * @param {string} path Path, e.g. `static/images/2024/photo.jpg`.
 * @param {string} basePath Base directory path, e.g. `static/images`. An empty string for the
 * repository root, below which every path sits as is.
 * @returns {string} Relative path, e.g. `2024/photo.jpg`. An empty string if the path is the base
 * directory itself or isn’t below it.
 */
export const getRelativePath = (path, basePath) => {
  if (basePath === '') {
    return path;
  }

  return path.startsWith(`${basePath}/`) ? path.slice(basePath.length + 1) : '';
};

/**
 * Get the path of the subfolder that a URL path points at, relative to the given asset folder.
 * @param {AssetFolderInfo} folder Asset folder.
 * @param {string} folderPath Folder path taken from the URL, e.g. `static/images/2024`.
 * @returns {string} Subfolder path, e.g. `2024`. An empty string for the folder root, or when the
 * folder can’t be browsed by subfolder.
 */
export const getSubfolderPath = (folder, folderPath) =>
  canBrowseSubfolders(folder)
    ? // `internalPath` is always a string for a folder that can be browsed
      getRelativePath(folderPath, /** @type {string} */ (folder.internalPath))
    : '';

/**
 * Find the asset folder that a URL path points at, along with the subfolder browsed below it.
 * @param {string} folderPath Folder path taken from the URL, e.g. `static/images/2024` or `-/all`.
 * @param {AssetFolderInfo} [knownFolder] Folder carried as history state. An internal path can be
 * shared by several folders, and the state settles which one is meant, so it takes precedence over
 * the lookup by path.
 * @returns {{ folder: AssetFolderInfo, subfolderPath: string } | undefined} Folder and subfolder
 * path, or `undefined` if the path doesn’t point at a configured folder or any subfolder of one.
 */
export const resolveAssetFolderPath = (folderPath, knownFolder = undefined) => {
  if (knownFolder) {
    return { folder: knownFolder, subfolderPath: getSubfolderPath(knownFolder, folderPath) };
  }

  const folders = allAssetFolders.current;

  const exactMatch = folders.find(({ internalPath, collectionName }) =>
    folderPath === '-/all'
      ? internalPath === undefined && collectionName === undefined
      : internalPath === folderPath,
  );

  if (exactMatch) {
    return { folder: exactMatch, subfolderPath: '' };
  }

  // The path can point below a folder. The deepest folder wins, so that a folder nested in another
  // gets its own subfolders rather than having them listed as the outer folder’s
  const parentFolder = folders
    .filter(
      (folder) =>
        canBrowseSubfolders(folder) &&
        (folder.internalPath === '' || folderPath.startsWith(`${folder.internalPath}/`)),
    )
    .sort(
      (a, b) =>
        /** @type {string} */ (b.internalPath).length -
        /** @type {string} */ (a.internalPath).length,
    )[0];

  return parentFolder
    ? { folder: parentFolder, subfolderPath: getSubfolderPath(parentFolder, folderPath) }
    : undefined;
};

/**
 * Path of the directory being browsed in the Asset Library, e.g. `static/images/2024`, which is
 * the selected asset folder’s `internalPath` joined with {@link selectedSubfolderPath}. It’s
 * `undefined` when the selected folder can’t be browsed by subfolder, in which case every asset
 * below the folder is listed at once.
 */
export const browsedDirPath = createDerivedState(() => {
  const folder = selectedAssetFolder.current;

  return canBrowseSubfolders(folder)
    ? createPath([folder.internalPath, selectedSubfolderPath.current])
    : undefined;
});

/**
 * Whether the directory being browsed in the Asset Library is, or is below, a folder the CMS itself
 * is usually served from, such as `admin`. Nothing can be uploaded or created there.
 */
export const browsingCmsFolder = createDerivedState(() =>
  isCmsFolderPath(browsedDirPath.current ?? ''),
);

/**
 * List the immediate subfolders of a directory, read off the paths of the files below it. A folder
 * isn’t an object of its own in a Git repository or an object storage bucket, so this is how the
 * folders are found. A folder path ending with a slash stands for an empty folder kept by a
 * placeholder, which has no file to be read off.
 * @param {object} args Arguments.
 * @param {string} args.dirPath Directory path. An empty string for the root.
 * @param {string[]} args.paths Paths of the files below the directory, at any depth. Paths outside
 * the directory are left alone.
 * @returns {AssetSubfolder[]} Subfolders, sorted by name.
 */
export const listSubfolders = ({ dirPath, paths }) => {
  const prefix = dirPath ? `${dirPath}/` : '';
  /** @type {Set<string>} */
  const names = new Set();

  paths.forEach((path) => {
    if (!path.startsWith(prefix)) {
      return;
    }

    const index = path.indexOf('/', prefix.length);

    if (index > prefix.length) {
      names.add(path.slice(prefix.length, index));
    }
  });

  return [...names].sort(compare).map((name) => ({ name, path: createPath([dirPath, name]) }));
};

/**
 * Get the names already taken in a directory, by a subfolder or a file, which a new or renamed
 * subfolder can’t be given.
 * @param {object} args Arguments.
 * @param {AssetSubfolder[]} args.subfolders Subfolders of the directory.
 * @param {string[]} args.fileNames Names of the files right in the directory.
 * @param {string} [args.exclude] Name of the subfolder being renamed, which it can keep.
 * @param {string} [args.dirPath] Path of the directory in the repository. When given, the names of
 * the subfolders leading to another configured asset folder nested in it, e.g. `projects` in
 * `static/uploads` for a collection’s `static/uploads/projects` folder, are taken too: such a
 * folder isn’t listed as a subfolder, as it’s browsed as a folder of its own, but a subfolder
 * renamed or created with its name would be merged into it.
 * @returns {string[]} Names.
 */
export const getTakenNames = ({
  subfolders,
  fileNames,
  exclude = undefined,
  dirPath = undefined,
}) => [
  ...subfolders.map(({ name }) => name).filter((name) => name !== exclude),
  ...fileNames,
  ...(dirPath === undefined
    ? []
    : listSubfolders({
        dirPath,
        // A trailing slash makes `listSubfolders` read the folder itself as a subfolder path
        paths: allAssetFolders.current
          .filter(({ internalPath, hasTemplateTags }) => internalPath && !hasTemplateTags)
          .map(({ internalPath }) => `${internalPath}/`),
      }).map(({ name }) => name)),
];

/**
 * Index the folders below a directory, read off the paths of the files below it.
 * @param {object} args Arguments.
 * @param {string} args.dirPath Directory path. An empty string for the root.
 * @param {string[]} args.paths Paths of the files below the directory, at any depth. Paths outside
 * the directory are left alone.
 * @returns {Map<string, Set<string>>} Names of the subfolders, keyed by the path of the directory
 * they’re in.
 */
const buildFolderTree = ({ dirPath, paths }) => {
  /** @type {Map<string, Set<string>>} */
  const tree = new Map();
  const prefix = dirPath ? `${dirPath}/` : '';

  paths.forEach((path) => {
    if (!path.startsWith(prefix)) {
      return;
    }

    // Add each folder on the way down to the file to the one above it
    let parentPath = dirPath;
    let start = prefix.length;
    let index = path.indexOf('/', start);

    while (index > start) {
      const name = path.slice(start, index);

      getOrCreate(tree, parentPath, () => new Set()).add(name);
      parentPath = createPath([parentPath, name]);
      start = index + 1;
      index = path.indexOf('/', start);
    }
  });

  return tree;
};

/**
 * List the immediate subfolders of a directory in a tree built with {@link buildFolderTree}.
 * @param {Map<string, Set<string>>} tree Folder tree.
 * @param {string} dirPath Directory path.
 * @returns {AssetSubfolder[]} Subfolders, sorted by name.
 */
const listChildFolders = (tree, dirPath) =>
  [...(tree.get(dirPath) ?? [])]
    .sort(compare)
    .map((name) => ({ name, path: createPath([dirPath, name]) }));

/**
 * Group file names by the directory they’re in.
 * @param {string[]} paths File paths.
 * @returns {Map<string, string[]>} Names, keyed by directory path.
 */
const groupNamesByDir = (paths) =>
  new Map(
    [...Map.groupBy(paths, getDirName)].map(([dirPath, filePaths]) => [
      dirPath,
      filePaths.map(getBaseName),
    ]),
  );

/**
 * Index of the folders in the repository, read off the paths of the assets and the Git config
 * files, rebuilt when either is replaced. Saving an entry looks up the folder of every file it
 * adds, so the paths are only gone through once rather than for each file.
 * @type {() => Map<string, Set<string>>}
 */
const getRepositoryFolderTree = memoizeOnSources(
  () => [allAssets.current, gitConfigFiles.current],
  (assets, configFiles) =>
    buildFolderTree({ dirPath: '', paths: [...assets, ...configFiles].map(({ path }) => path) }),
);

/**
 * Index of the names of the entry files, keyed by directory path, rebuilt when the entries are
 * replaced.
 * @type {() => Map<string, string[]>}
 */
const getEntryFileNamesByDir = memoizeOnSource(
  () => allEntries.current,
  (entries) =>
    groupNamesByDir(
      entries.flatMap(({ locales }) => Object.values(locales).map(({ path }) => path)),
    ),
);

/**
 * Index of the names of the Git config files, keyed by directory path, rebuilt when the files are
 * replaced.
 * @type {() => Map<string, string[]>}
 */
const getConfigFileNamesByDir = memoizeOnSource(
  () => gitConfigFiles.current,
  (configFiles) => groupNamesByDir(configFiles.map(({ path }) => path)),
);

/**
 * Get the names of every folder right in a directory of the repository, which a file renamed in it
 * can’t take: the folders holding assets or Git config files, whichever asset folder they belong
 * to, and the ones leading to a configured asset folder nested in the directory.
 * @param {string} dirPath Directory path. An empty string for the repository root.
 * @returns {string[]} Names.
 */
export const getFolderNamesInDir = (dirPath) =>
  getTakenNames({
    subfolders: listChildFolders(getRepositoryFolderTree(), dirPath),
    fileNames: [],
    dirPath,
  });

/**
 * Get the names of the files right in a directory of the repository that aren’t assets, which a
 * file renamed or uploaded there can’t take without overwriting them: the entry files, as in a Hugo
 * page bundle keeping its images next to its `index.md`, and the Git config files like `.gitkeep`.
 * @param {string} dirPath Directory path. An empty string for the repository root.
 * @returns {string[]} Names.
 */
export const getNonAssetFileNamesInDir = (dirPath) => [
  ...new Set([
    ...(getEntryFileNamesByDir().get(dirPath) ?? []),
    ...(getConfigFileNamesByDir().get(dirPath) ?? []),
  ]),
];

/**
 * Get the breadcrumb trail of the subfolder being browsed, from the location root down. Each
 * ancestor leads back to itself; the last item is the subfolder being browsed.
 * @param {object} args Arguments.
 * @param {string} args.rootLabel Label of the location root, e.g. the asset folder or the cloud
 * storage service.
 * @param {string[]} args.subfolderNames Names of the subfolders leading to the one being browsed,
 * from the location root down. Empty at the root.
 * @param {(ancestor: { depth: number, path: string }) => void} args.onBrowse Called when an
 * ancestor is selected, with how many subfolder names to keep, `0` being the root, and its path
 * relative to the root, which is an empty string for the root.
 * @returns {BreadcrumbItem[]} Items. Empty at the root, where there is no trail to show.
 */
export const getFolderBreadcrumbItems = ({ rootLabel, subfolderNames, onBrowse }) => {
  if (!subfolderNames.length) {
    return [];
  }

  return [
    ...[rootLabel, ...subfolderNames.slice(0, -1)].map((label, depth) => ({
      label,
      // eslint-disable-next-line jsdoc/require-jsdoc
      onClick: () => {
        onBrowse({ depth, path: subfolderNames.slice(0, depth).join('/') });
      },
    })),
    { label: /** @type {string} */ (subfolderNames.at(-1)) },
  ];
};

/**
 * Cache for {@link getOwnerFolderPath}, keyed by directory path, rebuilt when the asset folders
 * are replaced. Every Git config file is looked up each time subfolders are listed, and each lookup
 * goes through every folder.
 * @type {() => Map<string, string | undefined>}
 */
const getOwnerFolderPathCache = memoizeOnSource(
  () => allAssetFolders.current,
  () => new Map(),
);

/**
 * Get the `internalPath` of the asset folder that a directory belongs to: the folder at that path,
 * or else the deepest one it sits below.
 * @param {string} dirPath Directory path.
 * @returns {string | undefined} Folder path, or `undefined` if the directory is outside every
 * folder.
 */
const getOwnerFolderPath = (dirPath) =>
  getOrCreate(
    getOwnerFolderPathCache(),
    dirPath,
    () => resolveAssetFolderPath(dirPath)?.folder.internalPath,
  );

/**
 * Get the paths that the subfolders of a directory are read off: the assets and the Git config
 * files belonging to the same asset folder as the directory.
 * @param {object} args Arguments.
 * @param {string} args.dirPath Directory path. An empty string for the repository root.
 * @param {Asset[]} args.assets Assets below the directory, at any depth.
 * @returns {string[]} Paths.
 */
const getSubfolderSourcePaths = ({ dirPath, assets }) => {
  // A Git config file counts the same way as an asset: only when it belongs to the same asset
  // folder as the directory, so a nested asset folder isn’t listed for the `.gitkeep` it holds
  const ownerFolderPath = getOwnerFolderPath(dirPath);

  const configFiles = gitConfigFiles.current.filter(
    ({ path }) => getOwnerFolderPath(getDirName(path)) === ownerFolderPath,
  );

  return [...assets, ...configFiles].map(({ path }) => path);
};

/**
 * List the immediate subfolders of a directory. A folder isn’t an object of its own in a Git
 * repository, so the subfolders are read off the paths of the files below the directory: the assets
 * and, for a folder that holds no asset yet, the `.gitkeep` and other Git config files that keep
 * it in the repository.
 * @param {object} args Arguments.
 * @param {string} args.dirPath Directory path. An empty string for the repository root.
 * @param {Asset[]} args.assets Assets below the directory, at any depth. These are the assets of
 * the folder the directory belongs to, which leaves out the assets of another asset folder nested
 * in it, as those are that folder’s to list.
 * @returns {AssetSubfolder[]} Subfolders, sorted by name.
 */
export const getSubfolders = ({ dirPath, assets }) =>
  listSubfolders({ dirPath, paths: getSubfolderSourcePaths({ dirPath, assets }) });

/**
 * Get a function listing the immediate subfolders of a directory or of any directory below it, as
 * {@link getSubfolders} does, for walking the whole tree. The paths are read once, rather than once
 * per directory, which adds up to directories × assets for a folder with many subfolders.
 * @param {object} args Arguments.
 * @param {string} args.dirPath Path of the top directory. An empty string for the repository root.
 * @param {Asset[]} args.assets Assets below the directory, at any depth. These are the assets of
 * the folder the directory belongs to, so no directory below it belongs to another asset folder.
 * @returns {(dirPath: string) => AssetSubfolder[]} Function listing the subfolders of the top
 * directory or a directory below it, sorted by name.
 */
export const getSubfolderTree = ({ dirPath, assets }) => {
  const tree = buildFolderTree({ dirPath, paths: getSubfolderSourcePaths({ dirPath, assets }) });

  return (path) => listChildFolders(tree, path);
};

/**
 * Get the assets right in a directory, leaving out the ones in its subfolders.
 * @param {object} args Arguments.
 * @param {string} args.dirPath Directory path. An empty string for the repository root.
 * @param {Asset[]} args.assets Assets below the directory, at any depth.
 * @returns {Asset[]} Assets in the directory.
 */
export const getAssetsInDir = ({ dirPath, assets }) =>
  assets.filter(({ path }) => getDirName(path) === dirPath);

/**
 * Get the path of the directory that uploaded files are saved to, which is the target folder’s
 * `internalPath` joined with the subfolder path, if any.
 * @param {UploadingAssets} uploadingAssets Files to be uploaded and their target folder.
 * @returns {string | undefined} Directory path, or `undefined` if the target folder has no path,
 * which is the case for the All Assets folder.
 */
export const getUploadDirPath = ({ folder, subfolderPath }) =>
  folder?.internalPath !== undefined ? createPath([folder.internalPath, subfolderPath]) : undefined;

/**
 * Format a new subfolder name the way an uploaded file name is: sanitized, and slugified when the
 * `slugify_filename` option is enabled, so a folder created by hand is named like the files that
 * will be saved in it. A name Windows reserves for a device, like `con`, is numbered as `con-1`.
 * @param {string} name Name as typed.
 * @returns {string} Folder name. An empty string if nothing usable is left.
 */
export const formatSubfolderName = (name) => {
  const { slugify_filename: slugificationEnabled } = getDefaultMediaLibraryOptions().config;
  const folderName = sanitizeFileName(name.trim());

  // The whole name is slugified: unlike a file name, a folder name has no extension to keep, so a
  // dot in it is just another character. Slugifying can leave a name Windows reserves for a device,
  // like `aux` from `Aux!`, which `sanitizeFileName()` has renamed otherwise
  return slugificationEnabled
    ? renameReservedFileName(slugify(folderName, { fallback: false }))
    : folderName;
};

/**
 * Check whether a subfolder can be given the name typed in the New Folder dialog.
 * @param {object} args Arguments.
 * @param {string} args.name Name to check, as typed.
 * @param {string[]} args.takenNames Names of the files and folders already in the parent
 * directory. A Git tree can’t hold a blob and a subtree under one name, so a file name is taken as
 * well.
 * @returns {'empty' | 'invalid' | 'reserved' | 'duplicate' | undefined} What stops the name from
 * being used, or `undefined` if it can be used.
 */
export const validateSubfolderName = ({ name, takenNames }) =>
  // The files in a folder the CMS itself is usually served from are read-only
  validateNewFolderName({
    name,
    takenNames,
    format: formatSubfolderName,
    isReserved: isCmsFolderName,
  });
